INSERT INTO "snapshot_records" VALUES('requirementGaps',4,'REQ-GAP-005','{"id": "REQ-GAP-005", "text": "AI ''learning'' was not distinguished from uncontrolled model training.", "area": "AI governance", "gapType": "Ambiguous AI requirement", "potentialFailureMode": "AI could silently alter authoritative FMEA knowledge or produce untraceable decisions.", "severity": 10, "status": "Controlled", "linkedCharacteristic": "SWC-005", "source": "Architecture review"}');
INSERT INTO "snapshot_records" VALUES('learningCases',0,'CASE-001','{"id": "CASE-001", "title": "Blank GUI after schema extension", "domain": "Software FMEA", "failureMode": "Only static shell renders; dashboard/navigation content missing.", "cause": "Older browser snapshot overwrote newer embedded data structure; required arrays were absent.", "detection": "Browser showed header/sidebar shell and empty workspace.", "methods": ["5WHY", "Change Impact", "Migration Test"], "action": "Schema merge/migration with default fallback and render error boundary.", "result": "Newer versions tolerate older snapshots and surface diagnostics instead of white screen.", "lessons": ["Never replace new schema wholesale with old local snapshot.", "Validate and migrate before render.", "Keep reset/recovery path."], "sources": ["Open FMEA development history"], "approved": true, "qualityScore": 0.98, "approvalOrigin": "Inherited supplied historical approval; not a new approval by this development run"}');
INSERT INTO "snapshot_records" VALUES('learningCases',1,'CASE-002','{"id": "CASE-002", "title": "Risk Matrix lacked traceable contents", "domain": "Software FMEA", "failureMode": "Risk matrix visualized risk zones but did not show how many risks were in a cell or which risks they were.", "cause": "Mockup-focused rendering without data-driven bucket aggregation.", "detection": "User review of Risk Matrix.", "methods": ["5WHY", "Data Traceability"], "action": "Aggregate DFMEA/PFMEA by S/O, show count badge, drill down to filtered records.", "result": "Matrix is now a live view of FMEA data rather than a decorative heatmap.", "lessons": ["Every visualization must drill down to source objects.", "Count widgets must be computed from live data."], "sources": ["Open FMEA development history"], "approved": true, "qualityScore": 0.97, "approvalOrigin": "Inherited supplied historical approval; not a new approval by this development run"}');
INSERT INTO "snapshot_records" VALUES('learningCases',2,'CASE-003','{"id": "CASE-003", "title": "Risk trajectory had no selectable time basis", "domain": "Software FMEA", "failureMode": "Trajectory showed lifecycle progression but could not answer time-window questions.", "cause": "Lifecycle mockup implemented without calendar query controls.", "detection": "User requested days/weeks and selectable interval.", "methods": ["Requirement Gap", "Change Impact"], "action": "Add lifecycle/calendar mode, period selection and From/To dates.", "result": "Trajectory can support both development phase and calendar analysis.", "lessons": ["Every trend needs an explicit time basis.", "Timeline controls belong to the data query, not only to chart styling."], "sources": ["Open FMEA development history"], "approved": true, "qualityScore": 0.96, "approvalOrigin": "Inherited supplied historical approval; not a new approval by this development run"}');
INSERT INTO "snapshot_records" VALUES('learningCases',3,'CASE-004','{"id": "CASE-004", "title": "Fixed-size widgets failed browser resizing", "domain": "Software FMEA", "failureMode": "Widgets/matrices/tables do not fit when the browser is resized.", "cause": "Fixed grid widths and minimum sizes inherited from static mockups.", "detection": "Manual resize review.", "methods": ["6M", "Usability Review"], "action": "Responsive auto-fit grids, minmax(0,1fr), local overflow for dense data, breakpoints.", "result": "Primary UI adapts; dense tables/matrices use local scrolling where needed.", "lessons": ["Mockup pixels are reference, not runtime constraints.", "Responsive behavior is a software characteristic and testable requirement."], "sources": ["Open FMEA development history"], "approved": true, "qualityScore": 0.95, "approvalOrigin": "Inherited supplied historical approval; not a new approval by this development run"}');
INSERT INTO "snapshot_records" VALUES('learningCases',4,'CASE-005','{"id": "CASE-005", "title": "Change Impact charts lacked explanatory legends/time granularity", "domain": "Software FMEA", "failureMode": "Charts were visually present but decision context was incomplete.", "cause": "Dashboard chart decoration implemented before explicit interpretation requirements.", "detection": "User review.", "methods": ["Requirement Gap", "5WHY"], "action": "Add legend with values/percentages and day/week temporal buckets.", "result": "Change Impact supports interpretation and temporal investigation.", "lessons": ["A chart without legend/time basis can be misleading.", "Dashboard acceptance criteria must include decision usability."], "sources": ["Open FMEA development history"], "approved": true, "qualityScore": 0.94, "approvalOrigin": "Inherited supplied historical approval; not a new approval by this development run"}');
INSERT INTO "snapshot_records" VALUES('learningCases',5,'CASE-006','{"id": "CASE-006", "title": "Mockup pages existed without complete functional behavior", "domain": "Software FMEA", "failureMode": "Buttons/widgets look complete but actions do not modify or query shared data.", "cause": "Presentation layer developed ahead of universal action/transaction wiring.", "detection": "Feature-by-feature functional review.", "methods": ["8D", "5WHY", "Systemic corrective action"], "action": "Introduce shared CRUD, filters, transaction log, autosave, import/export and cross-module object links.", "result": "Open FMEA moves from dashboard prototype toward functional engineering application.", "lessons": ["No dead controls.", "All meaningful UI actions should map to commands/transactions.", "Use shared engines instead of page-specific scripts."], "sources": ["Open FMEA development history"], "approved": true, "qualityScore": 0.99, "approvalOrigin": "Inherited supplied historical approval; not a new approval by this development run"}');
INSERT INTO "snapshot_records" VALUES('learningCases',6,'CASE-HIST-001','{"id": "CASE-HIST-001", "title": "GUI shell visible but workspace blank", "domain": "Open FMEA Software / GUI", "failureMode": "Static shell renders while main application content fails to render.", "cause": "Version/schema/runtime integration regression; older state may override newer expected data shape.", "detection": "Observed functional regression in historical Open FMEA builds.", "methods": ["Validation Test", "Change Impact", "Regression Analysis"], "action": "Add migration/default merge, diagnostics and render error boundary.", "result": "Requires/feeds regression validation", "lessons": ["Mockup is a controlled validation baseline.", "GUI regression is a software failure mode.", "Do not accept feature work without regression validation."], "sources": ["history/html-releases-2026-09-13/chat_version/open_fmea_v1_1.html", "history/html-releases-2026-09-13/chat_version/open_fmea_v1_1_fixed.html"], "approved": true, "qualityScore": 0.99, "approvalOrigin": "Inherited supplied historical approval; not a new approval by this development run"}');
INSERT INTO "snapshot_records" VALUES('learningCases',7,'CASE-HIST-002','{"id": "CASE-HIST-002", "title": "Feature-complete appearance without feature-complete behavior", "domain": "Open FMEA Software / GUI", "failureMode": "Widgets/buttons are visible but do not execute the expected data operation.", "cause": "Presentation implementation progressed faster than shared command/data-flow wiring.", "detection": "Functional review across v1.2/v1.3 evolution.", "methods": ["Validation Test", "Change Impact", "Regression Analysis"], "action": "Shared CRUD/import/export/history/transaction runtime.", "result": "Requires/feeds regression validation", "lessons": ["Mockup is a controlled validation baseline.", "GUI regression is a software failure mode.", "Do not accept feature work without regression validation."], "sources": ["history/html-releases-2026-09-13/chat_version/open_fmea_v1_2.html", "history/html-releases-2026-09-13/chat_version/open_fmea_v1_3_functional.html"], "approved": true, "qualityScore": 0.99, "approvalOrigin": "Inherited supplied historical approval; not a new approval by this development run"}');
INSERT INTO "snapshot_records" VALUES('learningCases',8,'CASE-HIST-003','{"id": "CASE-HIST-003", "title": "GUI regression after adding new functionality", "domain": "Open FMEA Software / GUI", "failureMode": "A later build introduces features but moves away from supplied mockup layout or breaks previously accepted GUI behavior.", "cause": "No immutable per-page mockup baseline and no mandatory regression gate before release.", "detection": "Current user review of later Open FMEA builds.", "methods": ["Validation Test", "Change Impact", "Regression Analysis"], "action": "Treat every mockup as a validation baseline; every GUI change requires mockup parity + functional + responsive regression.", "result": "Requires/feeds regression validation", "lessons": ["Mockup is a controlled validation baseline.", "GUI regression is a software failure mode.", "Do not accept feature work without regression validation."], "sources": ["history/html-releases-2026-09-13/chat_version/open_fmea_v1_4_stable.html", "history/html-releases-2026-09-13/chat_version/open fmea ai html 1.7/open_fmea_v1_7_learning.html"], "approved": true, "qualityScore": 0.99, "approvalOrigin": "Inherited supplied historical approval; not a new approval by this development run"}');
INSERT INTO "snapshot_records" VALUES('learningCases',9,'CASE-HIST-004','{"id": "CASE-HIST-004", "title": "Visualization not connected to decision drill-down", "domain": "Open FMEA Software / GUI", "failureMode": "Risk matrix or chart exists visually but does not expose the underlying records or correct time interpretation.", "cause": "Visualization built as dashboard element rather than query over source-of-truth objects.", "detection": "User review and subsequent risk/timeline requirements.", "methods": ["Validation Test", "Change Impact", "Regression Analysis"], "action": "All visual widgets must be reversible to their source record set and explicit time basis.", "result": "Requires/feeds regression validation", "lessons": ["Mockup is a controlled validation baseline.", "GUI regression is a software failure mode.", "Do not accept feature work without regression validation."], "sources": ["history/html-releases-2026-09-13/chat_version/open_fmea_v1_4_stable.html"], "approved": true, "qualityScore": 0.99, "approvalOrigin": "Inherited supplied historical approval; not a new approval by this development run"}');
INSERT INTO "snapshot_records" VALUES('learningCases',10,'CASE-DFMEA-BASELINE-001','{"id": "CASE-DFMEA-BASELINE-001", "title": "DFMEA view must remain aligned with controlled mockup while functionality evolves", "domain": "Open FMEA Software / DFMEA module", "failureMode": "Feature additions alter DFMEA layout or remove expected mockup widgets/functions.", "cause": "No page-specific controlled baseline gate during implementation.", "detection": "User comparison against supplied DFMEA mockup.", "methods": ["Validation Test", "Change Impact", "Regression Analysis"], "action": "Lock DFMEA mockup as validation baseline and implement alternate DFMEA functions over the same shared records.", "result": "DFMEA development now requires visual + functional + responsive regression validation.", "lessons": ["Do not trade mockup parity for new feature work.", "Tabs are alternate views, not duplicate data stores.", "Every DFMEA chart must derive from current source records."], "sources": ["Supplied DFMEA mockup", "VAL-GUI-DFMEA-001"], "approved": false, "qualityScore": 0.4, "reviewStatus": "Requires validation evidence"}');
INSERT INTO "snapshot_records" VALUES('learningCases',11,'CASE-DEV-1-8-2','{"id": "CASE-DEV-1-8-2", "title": "Shared navigation, DFMEA stabilization and traceable analysis learning", "domain": "Open FMEA software design", "failureMode": "DFMEA/PFMEA regressions and analysis output disconnected from learning", "cause": "View-specific implementation and incomplete shared commands", "detection": "Source inspection and browser regression checks", "methods": ["Regression validation", "Change Impact", "Ishikawa / WHY learning workflow"], "action": "Use one embedded runtime with shared navigation, data queries, audit snapshots, structured analyses and in-browser diagnostics.", "result": "Development checks pass; in-browser diagnostics report four legacy data failure categories. Exact visual acceptance and other legacy pages remain pending.", "lessons": ["Keep application and validation logic in one HTML.", "Preserve historical engineering values until reviewed.", "Keep drafts separate from approved learning."], "sources": ["development/tests/smoke.cjs", "development/tests/verification.cjs", "architecture/open_fmea_implementation_audit.md"], "approved": false, "reviewStatus": "Draft — engineering and visual review pending", "qualityScore": 0.5, "sourceVersion": "1.8.2"}');
INSERT INTO "snapshot_records" VALUES('learningCases',12,'CASE-DEV-HOME-001','{"id": "CASE-DEV-HOME-001", "title": "Home dashboard acceptance requires source data and feature-level validation", "domain": "Open FMEA development process", "failureMode": "A rendered dashboard can retain hard-coded values, missing baseline panels and dead controls", "cause": "Home was not validated against a controlled feature acceptance matrix", "action": "Restore baseline panel hierarchy, query shared records, add source drill-down and validate commands, persistence and task scope", "result": "Functional correction tested; controlled visual acceptance remains pending", "methods": ["5WHY", "6M", "Change Impact", "Development task validation"], "lessons": ["Use feature-level acceptance, not page counts, to assess completion.", "Do not publish fixed example values as live dashboard results.", "Scope UI tests to the requested page."], "sources": ["DEV-TASK-HOME-001", "DEV-FIND-HOME-001", "DEV-FIND-HOME-002", "DEV-FIND-HOME-003", "DEV-FIND-HOME-004", "DEV-FIND-HOME-005", "development/tests/home-results.json"], "sourceType": "developmentFindings", "sourceVersion": "1.8.3", "approved": false, "reviewStatus": "Draft — human visual/engineering acceptance pending", "qualityScore": 0.5}');
