INSERT INTO "snapshot_records" VALUES('validationTests',0,'VAL-GUI-HOME-001','{"id": "VAL-GUI-HOME-001", "page": "Home", "baseline": "architecture/mockups/mockup-04-consolidated-home.png", "validationType": "Mockup parity + functional smoke", "acceptance": ["Consolidated Home hierarchy: six KPIs, three overview panels, four summary panels, context sidebar, project health and footer", "New FMEA, template selection and Open Project create/select real shared projects", "Six KPIs calculate from loaded records and drill down to exactly their sources", "5×5 overview groups stored 1–10 S/O into explicit paired bands; cells resolve exact records", "Validation stages and type coverage use linked validations; absent PM data is shown explicitly", "High risks sorted by current RPN; recent activity uses dated transactions/changes", "Engineering context tabs, process/step selection and characteristic source links work and persist", "Engineering, PM, operations and project-health widgets expose source records, formulas and empty states", "Import, report download, AI context and JSONL export operate from Home", "All Home panels and controls remain usable from 320 to 2560 px with local table scroll", "New project, context preference and task validation survive reload and portable export/import", "Home reads do not mutate engineering data; existing DFMEA edit, shared navigation and container load remain intact"], "type": ["visual", "functional", "data", "responsive", "traceability", "persistence", "cross-view consistency", "regression"], "requirements": ["Consolidated Home hierarchy: six KPIs, three overview panels, four summary panels, context sidebar, project health and footer", "New FMEA, template selection and Open Project create/select real shared projects", "Six KPIs calculate from loaded records and drill down to exactly their sources", "5×5 overview groups stored 1–10 S/O into explicit paired bands; cells resolve exact records", "Validation stages and type coverage use linked