INSERT INTO "snapshot_records" VALUES('validationTests',8,'VAL-GUI-DFMEA-001','{"id": "VAL-GUI-DFMEA-001", "page": "DFMEA", "baseline": "Supplied DFMEA mockup (current controlled baseline)", "validationType": "FMEA workflow", "acceptance": ["Header, KPI cards, toolbar, DFMEA tabs, filters, main DFMEA table, right item detail panel, RPN summary, RPN trend, Top 5 current RPN, Actions by Status and DFMEA Progress follow the supplied mockup information hierarchy.", "New DFMEA Item, Import, Export, Reports, View Options, Filters, row selection and detail editing are functional.", "DFMEA table exposes Element/Part, Function, Failure Mode, Effects, Severity, Causes, Occurrence, Prevention/Detection controls, RPN, Actions and Status.", "S/O/D updates recalculate risk and create an auditable transaction.", "All charts and counters are derived from live DFMEA/action data rather than fixed demo values.", "Structure Tree, Interface Matrix, Parameter Diagram, RPN Overview and Action Tracker are functional alternate views over the same DFMEA objects.", "Browser resize preserves the mockup hierarchy; dense DFMEA table uses local horizontal scrolling without breaking the page.", "Any later GUI drift from this controlled baseline creates a validation finding / software failure mode."], "type": ["visual", "functional", "data", "responsive", "regression"], "requirements": ["Header, KPI cards, toolbar, DFMEA tabs, filters, main DFMEA table, right item detail panel, RPN summary, RPN trend, Top 5 current RPN, Actions by Status and DFMEA Progress follow the supplied mockup information hierarchy.", "New DFMEA Item, Import, Export, Reports, View Options, Filters, row selection and detail editing are functional.", "DFMEA table exposes Element/Part, Function, Failure Mode, Effects, Severity, Causes, Occurrence, Prevention/Detection controls, RPN, Actions and Status.", "S/O/D updates recalculate risk and create an auditable transaction.", "All charts and counters are derived from live DFMEA/action data rather than fixed demo values.", "Structure Tree, Interface Matrix, Parameter Diagram, RPN Overview and Action Tracker are functional alternate views over the same DFMEA objects.", "Browser resize preserves the mockup hierarchy; dense DFMEA table uses local horizontal scrolling without breaking the page.", "Any later GUI drift from this controlled baseline creates a validation finding / software failure mode."], "status": "Not run", "lastRun": null, "result": null, "findings": [], "affectedObjects": [], "changeImpactIds": []}');
